import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.yZB1U4Nl.js";const p=JSON.parse('{"title":"Status and roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"status.md","filePath":"status.md"}'),r={name:"status.md"};function n(s,t,i,l,h,u){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="status-and-roadmap" tabindex="-1">Status and roadmap <a class="header-anchor" href="#status-and-roadmap" aria-label="Permalink to &quot;Status and roadmap&quot;">​</a></h1><p>What is built, what is planned, and what is not on the list. Nothing on this page is a date or a promise; planned items are listed in the order they are expected.</p><h2 id="where-vlo-runs-today" tabindex="-1">Where Vlo runs today <a class="header-anchor" href="#where-vlo-runs-today" aria-label="Permalink to &quot;Where Vlo runs today&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>Status</th></tr></thead><tbody><tr><td>A laptop or CI, on a SQLite file</td><td>Built</td></tr><tr><td>Any Node host or container, on Postgres</td><td>Built</td></tr><tr><td>Google Cloud Run</td><td>Built, with generated deploy files</td></tr><tr><td>Vercel (serverless, with a cron tick)</td><td>Built, with generated deploy files</td></tr><tr><td>Edge runtimes (Cloudflare Workers and Durable Objects)</td><td><strong>Not built.</strong> Planned as the next platform milestone</td></tr><tr><td>AWS (Lambda or ECS, Aurora, S3, EventBridge)</td><td>Planned, after Cloudflare</td></tr></tbody></table><p>Vlo needs Node 22.5 or later today.</p><h2 id="what-is-built" tabindex="-1">What is built <a class="header-anchor" href="#what-is-built" aria-label="Permalink to &quot;What is built&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Notes</th></tr></thead><tbody><tr><td>Kernel as a wasm module with no I/O and no imports</td><td>298 KB, capped at 1 MiB in CI</td></tr><tr><td>Write-set contract between kernel and storage</td><td>The kernel decides, the host persists</td></tr><tr><td>Postgres and SQLite journals</td><td>Postgres works behind transaction-mode poolers</td></tr><tr><td>Several orchestrators sharing one journal</td><td>On Postgres</td></tr><tr><td>Roles split across services</td><td>Push and pull workers anywhere, in any language</td></tr><tr><td>Serverless mode</td><td>A time-boxed drain plus a cron tick</td></tr><tr><td>Workflows</td><td>Hand-written reducers, <code>sequence</code>, <code>fanOut</code>, <code>fanOutRuns</code>, <code>waitFor</code>, <code>sleep</code>, child runs, <code>continue_as_new</code></td></tr><tr><td>Signals and signed links</td><td>Human approvals, webhooks, deadlines</td></tr><tr><td>Agents</td><td><code>@oona/vlo/agent</code>: decide, tool, evaluate, with budgets that park and tool calls that wait for approval</td></tr><tr><td>Usage accounting</td><td>Tokens, cost and CPU time banked in the kernel on every event</td></tr><tr><td>CLI</td><td><code>vlo dev</code>, <code>vlo serve</code>, <code>vlo doctor</code>, <code>vlo deploy</code></td></tr><tr><td>Blob stores</td><td>Local files and Google Cloud Storage</td></tr></tbody></table><h2 id="what-is-planned" tabindex="-1">What is planned <a class="header-anchor" href="#what-is-planned" aria-label="Permalink to &quot;What is planned&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Status</th></tr></thead><tbody><tr><td>Cloudflare: host in Workers, Durable Object journal, R2 blobs, alarm timers</td><td>Planned, the next platform milestone</td></tr><tr><td>Cross-run index on the edge</td><td>Planned; two designs recorded, not decided</td></tr><tr><td>Conformance test kit for third-party adapters</td><td>Planned</td></tr><tr><td>Native Rust host with no Node</td><td>Planned; <code>crates/traits</code> sketches the adapter traits</td></tr><tr><td>AWS adapters</td><td>Planned, after Cloudflare</td></tr><tr><td>Rust workflows as WASM components, Go and Python SDKs</td><td>Planned, later</td></tr><tr><td>A console: run tree, inbox, event timeline</td><td>Not built; see <a href="./observability#not-built-yet">observability.md</a></td></tr><tr><td>OpenTelemetry export</td><td>Not built</td></tr><tr><td>S3 and Vercel Blob stores</td><td>Not built</td></tr><tr><td>A lint for reducer purity</td><td>Not built</td></tr></tbody></table><h2 id="about-built-for-the-edge" tabindex="-1">About &quot;built for the edge&quot; <a class="header-anchor" href="#about-built-for-the-edge" aria-label="Permalink to &quot;About &quot;built for the edge&quot;&quot;">​</a></h2><p>The edge is the direction of the design, not a feature you can use today.</p><p>What is true now:</p><ul><li>The kernel compiles to <code>wasm32-unknown-unknown</code> with no imports, which is the form an edge runtime needs.</li><li>The kernel returns a declarative write-set, so any storage that can apply one atomic write can be a journal.</li><li>Every run has one journal and one writer, which is the shape of a Durable Object.</li></ul><p>What is not true yet:</p><ul><li>There is no Durable Object journal adapter and no Workers host.</li><li>The host opens its journal with <code>pg</code> or <code>node:sqlite</code>, both of which need Node.</li></ul><p>So the accurate statement is: Vlo is built to run at the edge, and it does not run there yet. See <a href="./limits#not-available-on-edge-runtimes-yet">limits.md</a>.</p><h2 id="known-weak-spots" tabindex="-1">Known weak spots <a class="header-anchor" href="#known-weak-spots" aria-label="Permalink to &quot;Known weak spots&quot;">​</a></h2><p>These are measured and documented, and they are work to do:</p><ul><li>About 15 database round trips per step, so the host must sit beside its journal.</li><li>One run that fans out very wide slows down sharply. Use child runs.</li><li>No benchmark at scale or over a network.</li></ul><p>Details are in <a href="./performance#what-these-numbers-are-not">performance.md</a> and <a href="./limits#known-weak-spots">limits.md</a>.</p><h2 id="stability" tabindex="-1">Stability <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;Stability&quot;">​</a></h2><p>Vlo is young. The kernel protocol is versioned and gated by golden fixtures, and the changelog records every release: see <a href="https://github.com/oonalab/vlo/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer"><code>../CHANGELOG.md</code></a>. Pin a version and read the changelog before you upgrade.</p>',22)])])}const b=e(r,[["render",n]]);export{p as __pageData,b as default};
